Here is the root cause:
The driver does not enforce the ISO 14443-3 limit of three cascade levels for NFC-A anti-collision. In digital_in_recv_sdd_res(), the number of cascade rounds is controlled entirely by the peer device via the cascade tag and cascade-incomplete bit, and the driver appends 3 or 4 bytes to target->nfcid1 without checking if the total length would exceed the allocated buffer size (NFC_NFCID1_MAXSIZE = 10). This allows a malicious peer to cause a heap buffer overflow.

Here is the patch:

 static void digital_in_recv_sdd_res(struct nfc_digital_dev *ddev, void *arg,
 				    struct sk_buff *resp)
 {
 	struct nfc_target *target = arg;
 	struct digital_sdd_res *sdd_res;
 	int rc;
 	u8 offset, size;
 	u8 i, bcc;

 	if (IS_ERR(resp)) {
 		rc = PTR_ERR(resp);
 		resp = NULL;
 		goto exit;
 	}

 	if (resp->len < DIGITAL_SDD_RES_LEN) {
 		PROTOCOL_ERR("4.7.2.8");
 		rc = -EINVAL;
 		goto exit;
 	}

 	sdd_res = (struct digital_sdd_res *)resp->data;

 	for (i = 0, bcc = 0; i < 4; i++)
 		bcc ^= sdd_res->nfcid1[i];

 	if (bcc != sdd_res->bcc) {
 		PROTOCOL_ERR("4.7.2.6");
 		rc = -EINVAL;
 		goto exit;
 	}

 	if (sdd_res->nfcid1[0] == DIGITAL_SDD_RES_CT) {
 		offset = 1;
 		size = 3;
 	} else {
 		offset = 0;
 		size = 4;
 	}

+	if (target->nfcid1_len + size > NFC_NFCID1_MAXSIZE) {
+		PROTOCOL_ERR("4.7.2.1");
+		rc = -EPROTO;
+		goto exit;
+	}
+
 	memcpy(target->nfcid1 + target->nfcid1_len, sdd_res->nfcid1 + offset,
 	       size);
 	target->nfcid1_len += size;

 	rc = digital_in_send_sel_req(ddev, target, sdd_res);

 exit:
 	dev_kfree_skb(resp);

 	if (rc) {
 		kfree(target);
 		digital_poll_next_tech(ddev);
 	}
 }



